/* Initialize options with default values */
void options_init(Options *opts) {
    if (!opts) return;

    /* Default values */
    opts->async_scroll = 0;
    opts->bold_chars = 0;
    opts->all_bold = 0;
    opts->force_term = 0;
    opts->linux_mode = 0;
    opts->old_scroll = 0;
    opts->only_shadows = 0;
    opts->lock_mode = 0;
    opts->rainbow_mode = 0;
    opts->lambda_mode = 0;
    opts->chars_change = 0;
    opts->screensaver = 0;
    opts->x_window = 0;
    opts->no_bold = 0;
    opts->help_flag = 0;
    opts->version_flag = 0;
    opts->message_flag = 0;
    opts->tty_flag = 0;
    opts->update_flag = 0;
    opts->color_flag = 0;

    opts->update_delay = 4;  /* Default delay */
    opts->color = NULL;      /* Default green */
    opts->message = NULL;
    opts->tty = NULL;

    opts->error_occurred = 0;
    opts->error_msg[0] = '\0';
}
