    /* Parse options */
    for (i = 1; i < argc; i++) {
        if (argv[i][0] != '-') {
            /* Non-option argument - ignore for now */
            continue;
        }

        if (argv[i][1] == '-') {
            /* Long option */
            if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0) {
                opts->help_flag = 1;
                options_print_usage(argv[0]);
                return 0;
            }
            if (strcmp(argv[i], "--version") == 0 || strcmp(argv[i], "-V") == 0) {
                opts->version_flag = 1;
                options_print_version();
                return 0;
            }
            continue;
        }

        /* Short options */
        switch (argv[i][1]) {
            case 'a':
                opts->async_scroll = 1;
                break;
            case 'b':
                opts->bold_chars = 1;
                break;
            case 'B':
                opts->all_bold = 1;
                break;
            case 'c':
                opts->only_shadows = 1;
                break;
            case 'f':
                opts->force_term = 1;
                break;
            case 'l':
                opts->linux_mode = 1;
                break;
            case 'L':
                opts->lock_mode = 1;
                break;
            case 'o':
                opts->old_scroll = 1;
                break;
            case 'h':
            case '?':
                opts->help_flag = 1;
                options_print_usage(argv[0]);
                return 0;
            case 'n':
                opts->no_bold = 1;
                break;
            case 's':
                opts->screensaver = 1;
                break;
            case 'x':
                opts->x_window = 1;
                break;
            case 'V':
                opts->version_flag = 1;
                options_print_version();
                return 0;
            case 'M':
                has_message = 1;
                if (i + 1 < argc) {
                    opts->message = argv[++i];
                }
                break;
            case 'u':
                has_update = 1;
                if (i + 1 < argc) {
                    opts->update_delay = atoi(argv[++i]);
                    if (opts->update_delay < 0 || opts->update_delay > 10) {
                        opts->error_occurred = 1;
                        snprintf(opts->error_msg, sizeof(opts->error_msg), 
                                 "Invalid update delay: %s (must be 0-10)", argv[i-1]);
                        return -1;
                    }
                }
                break;
            case 'C':
                has_color = 1;
                if (i + 1 < argc) {
                    opts->color = argv[++i];
                }
                break;
            case 'r':
                opts->rainbow_mode = 1;
                break;
            case 'm':
                opts->lambda_mode = 1;
                break;
            case 'k':
                opts->chars_change = 1;
                break;
            case 't':
                has_tty = 1;
                if (i + 1 < argc) {
                    opts->tty = argv[++i];
                }
                break;
            default:
                opts->error_occurred = 1;
                snprintf(opts->error_msg, sizeof(opts->error_msg), 
                         "Unknown option: %s", argv[i]);
                return -1;
        }
    }
