#include "error.h"
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>

/* Print error message to stderr and exit with code 1 */
void error_exit(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    fprintf(stderr, "\n");
    exit(1);
}

/* Print warning message to stderr */
void error_warn(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    fprintf(stderr, "\n");
}

/* Check if error occurred and print message */
int error_check(const char *msg) {
    if (msg) {
        fprintf(stderr, "Error: %s\n", msg);
    }
    return 1;
}
